#include "mesh.h"#include "256.h"#include "FileStuff.h"#include "BMP.h"OSErr getShadow ( Str255 thePlugName, meshHeader theMeshHeader );void reverse(char *, int);void SpinCursor( int initFlag );Boolean CommandPeriod ( void );OSErr getShadow ( Str255 thePlugName, meshHeader theMeshHeader ){//----------------------------------vars--------------------------------------------------	short		thePlugFileRef;	OSErr		theError;	FSSpec		thePlugFSSpec;	int i, x, y, theMark;	char	*theTexture;	long	theSize, theWidth, theHeight;	int		theMeshSize;									// in sections	struct sectionInfoEntry *sectionInfo;	_256Header thePlugHeader;	Myth256Palette thePalette;//----------------------------------------------------------------------------------------		// plug	theError = FSMakeFSSpec (0L, 0L, thePlugName, &thePlugFSSpec);	if ( theError != noErr )		return theError;	theError = FSpOpenDF ( &thePlugFSSpec, fsCurPerm, &thePlugFileRef );	if ( theError != noErr )		return theError;	FileRead ( &thePlugHeader, sizeof( _256Header ), thePlugFileRef );	thePlugHeader.sectionInfoOffset += sizeof(struct _256Header);			// add header length to offset	thePlugHeader.paletteOffset += sizeof(struct _256Header);				// ditto	thePlugHeader.colorMapOffset += sizeof(struct _256Header);	sectionInfo = (struct sectionInfoEntry *) NewPtr ( thePlugHeader.sections * sizeof(sectionInfoEntry) );	if ( sectionInfo == nil ){		FSClose ( thePlugFileRef );		return -1;	}	FileSeek ( thePlugFileRef, thePlugHeader.sectionInfoOffset );	FileRead (sectionInfo, 128 * thePlugHeader.sections, thePlugFileRef );	for( i = 0; i < thePlugHeader.sections; i++ )		sectionInfo[i].offset += (sizeof(struct _256Header) + sizeof(struct textureHeader));	theMeshSize = theMeshHeader.meshWidth * theMeshHeader.meshHeight;	theWidth = theMeshHeader.meshWidth * 256;	theHeight = theMeshHeader.meshHeight * 256;	theSize = theWidth * theHeight;	theTexture = (char *) NewPtr (theSize);	if ( theTexture == nil ){		DisposePtr ( (char *) sectionInfo );		FSClose ( thePlugFileRef );		return -1;	}	SpinCursor ( true );	theMark = 0;	for( y = 0; y < 2 * theMeshSize - theMeshHeader.meshWidth; y += (2 * theMeshHeader.meshWidth) ){ // sections y		for(i = 0; i < 256; i++){	// get one line from each section across			if ( CommandPeriod() ){				DisposePtr ( (char *) sectionInfo );				DisposePtr ( theTexture );				FSClose ( thePlugFileRef );				InitCursor();				return noErr; 			}			SpinCursor ( false );			for( x = (2 * theMeshHeader.meshWidth - 1); x >= 1; x -= 2 ){	// sections x				FileSeek ( thePlugFileRef, sectionInfo[x + y].offset + (i * 256) );				FileRead (theTexture + theMark, 256, thePlugFileRef);				reverse(theTexture + theMark, 256);				theMark += 256;			}		}	}	// Initialize the palette	for (i = 0; i < 256; i++){		thePalette.color[i].blue = i;		thePalette.color[i].green = i;		thePalette.color[i].red = i;	}	theError = writeBMP( "\p:Graphics.out:shadow.bmp", (long) theWidth, (long) theHeight, &thePalette, theTexture );	DisposePtr ( (char *) sectionInfo );	DisposePtr ( theTexture );	FSClose ( thePlugFileRef );		InitCursor();	return theError;}